package org.example.behavioral_pattern.strategy_pattern.spring_boot;import org.example.behavioral_pattern.strategy_pattern.delivery.EShippingType;import org.example.behavioral_pattern.strategy_pattern.delivery.Order;import org.springframework.beans.factory.InitializingBean;import org.springframework.stereotype.Service;import java.util.EnumMap;import java.util.List;@Servicepublic class ShippingService implements InitializingBean {    private final EnumMap<EShippingType, ShippingStrategy> strategyMap = new EnumMap<>(EShippingType.class);    private final List<ShippingStrategy> strategies;    public ShippingService(List<ShippingStrategy> strategies) {        this.strategies = strategies;    }    public int getShippingFee(Order order, EShippingType type) {        ShippingStrategy strategy = strategyMap.getOrDefault(type, strategyMap.get(EShippingType.STANDARD));        return strategy.calculateFee(order);    }    @Override    public void afterPropertiesSet() {        for (ShippingStrategy strategy : strategies) {            strategyMap.put(strategy.getType(), strategy);        }    }}